  ('r', '∀x₁:[ℕ | GT(11)], ∃x₂:[ℕ | LT(5)] [ GT(x₁, x₂) ]', '∀x₁:[ℕ | GT(11)], ∃x₂:[ℕ | LT(5)] [ GT(x₁, x₂) ]', '∀x₁:[ℕ|GT(11)], ∃x₂:[ℕ|LT(5)]', TRUE, TRUE, 1092, 'Lean (version 4.33.1, x86_64-w64-windows-gnu, commit 819816b2e0a3bf405af45ae5c7af2491d8f5bee6, Release)', '2026-09-11T23:38:44.941Z', 'theorem r_proof (x1 : Nat) (hx1 : x1 > 11) : ∃ x2 < 5, x1 > x2 := ⟨0, by decide, by omega⟩', 'For any x₁ > 11, choose x₂ = 0 (< 5) satisfying x₁ > x₂'),
