  ('s', '∀x₁:[ℕ | EVEN], ∃x₂:[ℕ | LT(x₁)] [ LT(x₂, x₁) ]', '∀x₁:[ℕ | EVEN], ∃x₂:[ℕ | LT(x₁)] [ LT(x₂, x₁) ]', '∀x₁:[ℕ|EVEN], ∃x₂:[ℕ|LT(x₁)]', TRUE, TRUE, 1063, 'Lean (version 4.33.1, x86_64-w64-windows-gnu, commit 819816b2e0a3bf405af45ae5c7af2491d8f5bee6, Release)', '2026-09-11T23:38:44.941Z', 'theorem s_proof (x1 : Nat) (hx1 : x1 % 2 = 0 ∧ x1 > 0) : ∃ x2 < x1, x2 < x1 := ⟨0, by omega, by omega⟩', 'Dependent lower bound satisfied by choosing x₂ = 0 < x₁'),
  ('exp:s', '∀x₁:[ℕ | EVEN], ∃x₂:[ℕ | LT(x₁)] [ LT(x₂, x₁) ]', '∀x₁:[ℕ | EVEN], ∃x₂:[ℕ | LT(x₁)] [ LT(x₂, x₁) ]', '∀x₁:[ℕ|EVEN], ∃x₂:[ℕ|LT(x₁)]', TRUE, TRUE, 1063, 'Lean (version 4.33.1, x86_64-w64-windows-gnu, commit 819816b2e0a3bf405af45ae5c7af2491d8f5bee6, Release)', '2026-09-11T23:38:44.941Z', 'theorem s_proof (x1 : Nat) (hx1 : x1 % 2 = 0 ∧ x1 > 0) : ∃ x2 < x1, x2 < x1 := ⟨0, by omega, by omega⟩', 'Dependent lower bound satisfied by choosing x₂ = 0 < x₁'),
