  ('ras', '∃x₁:ℕ, ∃x₂:ℕ [ GT(x₁,x₂)∧LT(x₁,x₂) ]', '∃x₁:ℕ, ∃x₂:ℕ [ GT(x₁,x₂)∧LT(x₁,x₂) ]', '∃x₁:ℕ, ∃x₂:ℕ', FALSE, TRUE, 1235, 'Lean (version 4.33.1, x86_64-w64-windows-gnu, commit 819816b2e0a3bf405af45ae5c7af2491d8f5bee6, Release)', '2026-09-11T23:38:44.941Z', 'theorem ras_refutation : ¬(∃ x1 x2 : Nat, x1 > x2 ∧ x1 < x2) := by intros h; rcases h with ⟨x1, x2, h1, h2⟩; omega', 'Contradiction refutation: no pair of natural numbers can simultaneously satisfy x₁ > x₂ and x₁ < x₂'),
  ('exp:ras', '∃x₁:ℕ, ∃x₂:ℕ [ GT(x₁,x₂)∧LT(x₁,x₂) ]', '∃x₁:ℕ, ∃x₂:ℕ [ GT(x₁,x₂)∧LT(x₁,x₂) ]', '∃x₁:ℕ, ∃x₂:ℕ', FALSE, TRUE, 1235, 'Lean (version 4.33.1, x86_64-w64-windows-gnu, commit 819816b2e0a3bf405af45ae5c7af2491d8f5bee6, Release)', '2026-09-11T23:38:44.941Z', 'theorem ras_refutation : ¬(∃ x1 x2 : Nat, x1 > x2 ∧ x1 < x2) := by intros h; rcases h with ⟨x1, x2, h1, h2⟩; omega', 'Contradiction refutation: no pair of natural numbers can simultaneously satisfy x₁ > x₂ and x₁ < x₂'),
